						panel.dispose();
						return;
					}
					await setupSessionPanel(
						panel,
						sessionManager,
						sessionId,
						sessionPath,
					);
				} catch (err) {
					console.error(
						"[CodePi] Failed to restore session",
						sessionId,
						":",
						err,
					);
					panel.dispose();
				}
			},
		}),
	);

