		return pi.createAgentSession({
			resourceLoader: loader,
			cwd: opts.cwd,
			agentDir: opts.agentDir,
			noTools: "builtin",
			customTools: createVscodeTools(state.review),
			sessionManager: opts.sessionManager,
			sessionStartEvent: { type: "session_start", reason: "startup" },
		});
	};

	const runtime = await pi.createAgentSessionRuntime(createRuntime, {
		cwd: workspaceRoot,
		agentDir,
		sessionManager: state.sessionManager,
	});
	state.runtime = runtime;

	state.tui = new pi.InteractiveMode(runtime, {
		terminal: state.pty,
		verbose: true,
	});

	state.isBackendReady = true;
	state.isBusy = true;
	treeProvider?.refresh();

	// run() resolves when the TUI exits (e.g. /quit) → close the panel tab.
	void state.tui
		.run()
		.then(() => {
			state.panel.dispose();
